import React, { useState, useEffect } from 'react';
import { useOutletContext } from 'react-router-dom';

const Ins_P2 = () => {
  const context = useOutletContext();
  const [data, setData] = useState(context?.ins?.data);
  useEffect(() => { if (context?.ins?.data) setData(context.ins.data); }, [context?.ins?.data]);

  return (
    <div className="summary-box">
      <h3>Actuarial Risk Assessment Model</h3>
      <p>{data ? `Compliance index: ${data.score || 'N/A'}% integrity.` : "Awaiting stream..."}</p>
      <p style={{ fontSize: '0.8rem', color: '#64748b' }}>{data?.result}</p>
    </div>
  );
};
export default Ins_P2;
